import torch, torch.nn as nn
# --- reuse Tent utilities ----------------------------------------------
from tent import softmax_entropy, configure_model

class HyperBN(nn.Module):
    """A BN layer whose affine params are given by a tiny MLP."""
    def __init__(self, channels):
        super().__init__()
        self.gamma0 = nn.Parameter(torch.ones(channels), requires_grad=False)
        self.beta0  = nn.Parameter(torch.zeros(channels), requires_grad=False)
        self.mlp = nn.Sequential(
            nn.Linear(2, 32), nn.ReLU(), nn.Linear(32, 2))  # maps (mu, sigma) -> d_gamma, d_beta
    def forward(self, x):
        mu  = x.mean([0, *range(2, x.dim())])
        sig = x.std ([0, *range(2, x.dim())])
        d   = self.mlp(torch.stack([mu, sig], 1))
        gamma = self.gamma0 + d[:,0]
        beta  = self.beta0  + d[:,1]
        x_hat = (x - mu[None,:,None,None]) / (sig[None,:,None,None] + 1e-5)
        return gamma[None,:,None,None]*x_hat + beta[None,:,None,None]

class HyperTTA(nn.Module):
    def __init__(self, pretrained):
        super().__init__()
        self.net = configure_model(pretrained)  # puts BN in train mode etc.
        # replace every BN with HyperBN
        for name, module in list(self.net.named_modules()):
            if isinstance(module, nn.BatchNorm2d):
                hyp = HyperBN(module.num_features)
                setattr(self.net, name.split('.')[-1], hyp)
        self.no_grad_params()
    def no_grad_params(self):
        for p in self.net.parameters():
            p.requires_grad = False
        # only mlp weights are trainable during optional refinement
        for m in self.net.modules():
            if isinstance(m, HyperBN):
                for p in m.mlp.parameters():
                    p.requires_grad = True
    def forward(self, x, refine=False):
        if refine:
            # one entropy step on HyperBN-MLP params
            out = self.net(x)
            loss = softmax_entropy(out).mean()
            loss.backward(); self.opt.step(); self.opt.zero_grad()
        return self.net(x)

