class StatEncoder(nn.Module):
    def forward(self, feats):          # feats: list of tensors per norm layer
        m = []; v = []; sk = []; ku = []
        for t in feats:
            m.append(t.mean(dim=[0,*range(2,t.dim())]))
            v.append(t.var (dim=[0,*range(2,t.dim())]))
            sk.append(((t-m[-1])**3).mean([0,*range(2,t.dim())]))
            ku.append(((t-m[-1])**4).mean([0,*range(2,t.dim())]))
        return torch.cat([*m,*v,*sk,*ku],0)

class STAMP(nn.Module):
    def __init__(self, backbone):
        super().__init__()
        self.backbone = backbone.eval()      # frozen γ0,β0 stored
        self.enc = StatEncoder()
        S = sum(4*m.num_features for m in backbone.modules() if isinstance(m, (nn.BatchNorm2d, nn.LayerNorm, nn.GroupNorm, nn.InstanceNorm2d)))
        P = sum(2*m.num_features for m in backbone.modules() if isinstance(m, (nn.BatchNorm2d, nn.LayerNorm, nn.GroupNorm, nn.InstanceNorm2d)))
        self.hyper = nn.Sequential(nn.Linear(S,1024), nn.ReLU(), nn.Linear(1024,P))
        self._split = [m.num_features for m in backbone.modules() if isinstance(m,(nn.BatchNorm2d,nn.LayerNorm,nn.GroupNorm,nn.InstanceNorm2d))]

    @torch.no_grad()
    def forward(self,x):
        feats = []
        def _hook(_,inp,out): feats.append(out)
        hs=[]; handles=[m.register_forward_hook(_hook) for m in self.backbone.modules() if isinstance(m,(nn.BatchNorm2d,nn.LayerNorm,nn.GroupNorm,nn.InstanceNorm2d))]
        y = self.backbone(x)              # 1st pass to collect stats
        s = self.enc(feats)
        delta = self.hyper(s)
        idx=0
        for m,c in zip([m for m in self.backbone.modules() if isinstance(m,(nn.BatchNorm2d,nn.LayerNorm,nn.GroupNorm,nn.InstanceNorm2d))], self._split):
            m.weight = nn.Parameter(m.weight + delta[idx:idx+c]); idx+=c
            m.bias   = nn.Parameter(m.bias   + delta[idx:idx+c]); idx+=c
        for h in handles: h.remove()
        return self.backbone(x)           # 2nd pass with adapted params
